var sessionToChat = new TtlMap(24 * 60 * 60 * 1e3);
function registerSessionChat(sessionId, chatId, chatType) {
  sessionToChat.set(sessionId, { chatId, chatType });
}
function getChatIdBySession(sessionId) {
  return sessionToChat.get(sessionId)?.chatId;
}
function getChatInfoBySession(sessionId) {
  return sessionToChat.get(sessionId);
}

// src/feishu/sender.ts
async function wrapSendCall(fn, log, action, idExtractor = (res) => res?.data?.message_id ?? "") {
  try {
    const res = await fn();
    return { ok: true, messageId: idExtractor(res) };
  } catch (err) {
    const larkErr = err != null && typeof err === "object" ? err : {};
    const parts = [
      larkErr.code !== void 0 ? `code=${larkErr.code}` : null,
      typeof larkErr.msg === "string" ? `msg=${larkErr.msg}` : null,
      typeof larkErr.logId === "string" ? `logId=${larkErr.logId}` : null
    ].filter(Boolean).join(", ");
    const message = err instanceof Error ? err.message : String(err);
    log?.("error", `\u98DE\u4E66\u6D88\u606F\u64CD\u4F5C\u5931\u8D25: ${action}`, {
      error: message,
      ...parts ? { diagnostics: parts } : {}
    });
    return { ok: false, error: parts ? `${message} (${parts})` : message };
  }
}
function createChatMessage(client, chatId, msgType, content, log) {
  const receiveId = chatId.trim();
  if (!receiveId) {
    log?.("error", "\u98DE\u4E66\u6D88\u606F\u53D1\u9001\u5931\u8D25: \u7F3A\u5C11 chat_id", { msgType });
    return Promise.resolve({ ok: false, error: "No chat_id provided" });
  }
  return wrapSendCall(
    () => client.im.message.create({
      params: { receive_id_type: "chat_id" },
      data: {
        receive_id: receiveId,
        msg_type: msgType,
        content
      }
    }),
    log,
    `create:${msgType}`
  );
}
async function sendTextMessage(client, chatId, text, log) {
  return createChatMessage(client, chatId, "text", JSON.stringify({ text }), log);
}
async function updateMessage(client, messageId, text, log) {
  return wrapSendCall(
    () => client.im.message.update({
      path: { message_id: messageId },
      data: {
        msg_type: "text",
        content: JSON.stringify({ text })
      }
    }),
    log,
    "update",
    // update API 不返回 message_id，因此直接回填调用方传入的 messageId。
    () => messageId
  );
}
async function deleteMessage(client, messageId, log) {
  try {
    await client.im.message.delete({ path: { message_id: messageId } });
  } catch (err) {
    log?.("error", "\u5220\u9664\u98DE\u4E66\u6D88\u606F\u5931\u8D25", {
      messageId,
      error: err instanceof Error ? err.message : String(err)
    });
  }
}
async function sendInteractiveCard(client, chatId, card, log) {
  return createChatMessage(client, chatId, "interactive", JSON.stringify(card), log);
}
async function sendCardMessage(client, chatId, cardId, log) {
  return createChatMessage(
    client,
    chatId,
    "interactive",
    JSON.stringify({ type: "card", data: { card_id: cardId } }),
    log
  );
}

